function validarCorreo(t){return/^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/.test(t)}function soloLetras(t){return/^[A-Za-zÁÉÍÓÚáéíóúÑñÜü\s]+$/.test(t)}function validarLongitud(t,e){return String(t).length<=e}function calcularEdad(t){const e=new Date(t),a=new Date;let n=a.getFullYear()-e.getFullYear();const r=a.getMonth()-e.getMonth();return(r<0||0===r&&a.getDate()<e.getDate())&&n--,n}function esMayorDeEdad(t){return calcularEdad(t)>=18}function validarPassword(t){return/.{8,}/.test(t)&&/[A-Z]/.test(t)&&/[a-z]/.test(t)&&/[0-9]/.test(t)&&/[^A-Za-z0-9]/.test(t)}function validarRango(t,e,a){return t>=e&&t<=a}function validarUsuario(t){return/^[A-Za-z0-9_]{4,20}$/.test(t)}
